<script>
const months=["January","February","March","April","May","June","July"];
let values=[[65,8,90,81,56,55,40],[21,48,40,19,96,27,99]];
let showDots=false;
const xs=[61,162,263,364,465,566,667], base=305, scale=2.2;
function smoothPath(vals){
  let p=`M ${xs[0]} ${base-vals[0]*scale}`;
  for(let i=0;i<vals.length-1;i++){
    const x1=xs[i], y1=base-vals[i]*scale, x2=xs[i+1], y2=base-vals[i+1]*scale;
    const mid=(x1+x2)/2;
    p+=` C ${mid} ${y1}, ${mid} ${y2}, ${x2} ${y2}`;
  }
  return p+` L ${xs[xs.length-1]} ${base} L ${xs[0]} ${base} Z`;
}
function render(){
  blueArea.setAttribute("d",smoothPath(values[0]));
  greenArea.setAttribute("d",smoothPath(values[1]));
  labels.innerHTML="";
  values.forEach((row,ri)=>row.forEach((v,i)=>{
    const t=document.createElementNS("http://www.w3.org/2000/svg","text");
    t.setAttribute("x",xs[i]+(i===0?2:0)); t.setAttribute("y",base-v*scale-7);
    t.setAttribute("text-anchor",i===0?"start":"middle"); t.textContent=v; labels.appendChild(t);
  }));
  dots.innerHTML="";
  if(showDots) values.forEach((row,ri)=>row.forEach((v,i)=>{
    const c=document.createElementNS("http://www.w3.org/2000/svg","circle");
    c.setAttribute("cx",xs[i]);c.setAttribute("cy",base-v*scale);c.setAttribute("r",5);
    c.setAttribute("fill",ri?"#27c86b":"#328fc7");dots.appendChild(c);
  }));
}
function commit(e){
  const cell=e.currentTarget, r=+cell.dataset.r,c=+cell.dataset.c;
  let n=parseFloat(cell.textContent.trim());
  if(!isNaN(n)){n=Math.max(0,Math.min(100,n));values[r][c]=n;cell.textContent=n}
  render();
}
document.querySelectorAll('[contenteditable]').forEach(cell=>{
  cell.addEventListener("focus",()=>cell.classList.add("selected"));
  cell.addEventListener("blur",e=>{e.currentTarget.classList.remove("selected");commit(e)});
  cell.addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();e.currentTarget.blur()}});
});
document.querySelector(".point-toggle").addEventListener("click",()=>{
  showDots=!showDots;
  pointOptions.style.display=pointOptions.style.display==="none"?"block":"none";
  render();
});
document.querySelector(".switch").addEventListener("click",()=>{showDots=!showDots;render()});
render();
</script>
